import numpy as np, json
path = "/home/ly/small_object_ideas_20260928/idea-stage/infrared_problem_screen_20261009/runtime/first_val_inference.npz"
summary = {}
with np.load(path, allow_pickle=False) as archive:
    for key in archive.files:
        arr = archive[key]
        item = {"shape": list(arr.shape), "dtype": str(arr.dtype)}
        if arr.dtype.kind in "biufc":
            item["all_finite"] = bool(np.isfinite(arr).all())
            item["min"] = float(arr.min()) if arr.size else None
            item["max"] = float(arr.max()) if arr.size else None
            if arr.size <= 1024:
                item["values"] = arr.tolist()
        elif arr.dtype.kind in "US":
            item["values"] = arr.tolist()
        summary[key] = item
print(json.dumps({"cpu_only": True, "npz": path, "arrays": summary}, indent=2))
